"""Bounded post-block assessment, pin/process verification and evidence inventory."""
import collections,datetime,fcntl,hashlib,json,math,shutil,statistics,subprocess
from pathlib import Path
import psutil
H=Path(__file__).resolve().parent;ROOT=H.parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,x):p.write_text(json.dumps(x,indent=2)+'\n')
def main():
 manifest=ROOT/'evidence/live-optimization-2080ti-20261103/triage-confirmation-frozen.json';gate=ROOT/'evidence/live-optimization-2080ti-20261103/triage-confirmation-launch-gate.json';m=json.loads(manifest.read_text());g=json.loads(gate.read_text());state=json.loads((H/'live-nov3-triage-confirmation-custody.json').read_text());a=json.loads((H/'live-nov3-triage-confirmation-independent-analysis.json').read_text())
 assert sha(manifest)==state['manifest_sha256']==g['manifest_sha256'] and sha(gate)==state['gate_sha256'] and g['gate_open']
 bad=[p for p,v in m['file_pins'].items() if not (ROOT/p).is_file() or sha(ROOT/p)!=v];assert not bad,bad
 assert state['status']=='complete' and len(state['runs'])==27 and not state['owned_descendants_remaining']
 if psutil.pid_exists(state['supervisor_pid']):assert psutil.Process(state['supervisor_pid']).create_time()!=state['supervisor_create_time'],'Owned supervisor still alive'
 assert all(r['owned_descendants_remaining']==[] for r in state['runs'])
 gpu=subprocess.check_output(['nvidia-smi','--query-compute-apps=pid,process_name','--format=csv,noheader'],text=True).strip();assert not gpu
 with open('/tmp/vllm-semantic-cache-gpu.lock','a') as f:fcntl.flock(f,fcntl.LOCK_EX|fcntl.LOCK_NB);fcntl.flock(f,fcntl.LOCK_UN)
 before=shutil.disk_usage(H).free;files=[]
 for item in m['execution_order']:
  files.extend(p for p in (H/'runs'/item['name']).rglob('*') if p.is_file())
  files.append(H/(item['name']+'-driver-console.log.gz'))
 assert all(p.is_file() for p in files);assert not [p for p in files if p.suffix in ['.log','.jsonl']]
 rows=list(a['rows'].values());http={'all_qualified':all(r['HTTP_receipt']['qualified'] for r in rows),'total_HTTP_attempts':sum(r['HTTP_receipt']['expected_total_HTTP_requests'] for r in rows),'generations':sum(r['HTTP_receipt']['generation_rows'] for r in rows),'hints':sum(r['HTTP_receipt']['hint_rows'] for r in rows),'intentional_hint_cancellations':sum(len(r['HTTP_receipt']['intentional_hint_cancellations']) for r in rows),'unexpected_transport_exceptions':sum(len(r['HTTP_receipt']['unexpected_transport_exceptions']) for r in rows),'connection_reuse':sum(r['HTTP_receipt']['counts']['connection_reuse'] for r in rows)}
 resources={};mechanism={}
 for arm in ['native','candidate','original_eager']:
  rr=[r for r in rows if r['arm']==arm]
  resources[arm]={'runs':len(rr),'configured_cpu_kv_mib':sorted(set(r['host_resources']['configured_cpu_kv_bytes']/2**20 for r in rr)),'actual_locked_pinned_host_bytes':None,'CUDA_load_peaks_unique':list({json.dumps(r['resources']['cuda_load_peaks'],sort_keys=True):r['resources']['cuda_load_peaks'] for r in rr}.values())}
  for key in ['serving_nvml_peak_mib','startup_nvml_peak_mib','sampled_server_child_cpu_s','sampled_server_summed_rss_peak_mib','sampled_driver_cpu_s']:
   vals=[r['resources'][key] for r in rr];assert all(v is not None for v in vals);resources[arm][key]={'min':min(vals),'max':max(vals),'mean':statistics.mean(vals),'values':vals}
  resources[arm]['swap']={stage:{key:{'min_delta_bytes':min(vals),'max_delta_bytes':max(vals),'sum_delta_bytes':sum(vals),'values':vals} for key in ['swap_in_bytes','swap_out_bytes'] for vals in [[r['host_resources'][stage][key]['delta'] for r in rr]]} for stage in ['startup','serving']}
 for seed in [7703,8803,9901]:
  mechanism[str(seed)]={}
  for arm in ['native','candidate']:
   rr=[r for r in rows if r['partition']==seed and r['arm']==arm]
   mechanism[str(seed)][arm]={'local_compute_first_admission_tokens':[r['first_prefill_attribution']['tokens']['local_compute'] for r in rr],'external_first_admission_tokens':[r['first_prefill_attribution']['tokens']['external_kv_transfer'] for r in rr],'CPU_evicted_blocks':[r['scheduler_counts'].get('cpu_evicted_blocks') for r in rr],'H2D_bytes':[r['transfers']['CPU_to_GPU'] for r in rr],'preemptions':[r['first_prefill_attribution']['preemptions'] for r in rr]}
 anchors=[]
 for x in a['descriptive_anchors']:
  anchors.append({**x,'changes_percent':{k:100*math.expm1(v) for k,v in x['differences'].items() if k.endswith('log_ratio')}})
 variant={'recommendation':'A small opt-in conservative CPU-hole bridge is reasonable next discovery; no performance/correctness claim before validation. Prefer over skipping all GPU-resident prefixes.','mechanism':'Preserve existing ready CPU prefix. Only when its length is less than native contiguous GPU prefix length, append ready CPU suffix beginning at that GPU frontier. This can protect an immediately restorable combined-tier prefix missed by root-only CPU prefix inspection.','ordering':'Call refresh once with deduplicated ready_prefix + bridged_suffix. Existing implementation reverses keys before moving to MRU, preserving prefix-root priority. Two separate refresh calls would make suffix hotter than roots.','guardrails':['Keep all existing namespace/generation/causal/boundary checks and narrow TP1 dense single-group support.','Use native read-only get_cached_block index; no references, reservations, copy, lease, future return data or adaptive queue promotion.','Unavailable GPU index falls back to current behavior; CPU readiness holes stop the suffix.','No schema claim that combined tiers guarantee future availability: GPU or CPU can evict after hint.','Bound work to observed prefix keys; no growing per-hint history in audit-off mode.'],'negative_controls':['No GPU prefix; GPU shorter/equal CPU prefix; missing index: byte-for-byte same refresh order as current.','CPU hole covered by GPU prefix plus ready suffix: touch intended suffix once, no gap beyond first unready CPU suffix.','Fully GPU resident: preserve current ready CPU prefix, do not skip existing benefit.','Stale generation/namespace/clock/source: no touch; all existing rejections unchanged.','Queue membership/ARC adaptive target/refcounts/free queues/transfers unchanged; combined-call recency order verified.'],'risks':['Extra touches can displace other useful pending prefixes.','Subsequent GPU eviction can make retained CPU suffix unusable until missing roots recomputed.','Extra hint-time key lookups cost CPU/RPC latency; gains must exceed them.'],'evaluation':'Use already-consumed inputs for finite discovery, retain all three positive/negative partitions. Do not postselect 8803 or assume CPU holes caused existing regressions. Any later confirmation needs genuinely fresh input sets and new pins.'}
 assessment={'schema':'astra-fresh-triage-confirmation-assessment-v1','manifest_sha256':sha(manifest),'all_27_completed':True,'natural_eos':1944,'paired_natural_eos_per_arm':864,'http':http,'all_executed_lean_configuration_matches':all(r['measurement']['matches_frozen_lean'] for r in rows),'all_optional_observer_counts_explicit_zero':all(all(r['measurement'][k]==0 for k in ['residency_samples','readmission_events','lookup_observer_events']) for r in rows),'all_first_admission_attribution_reconciles':all(r['first_prefill_attribution']['reconciles'] is True for r in rows),'all_zero_preemptions':all(r['first_prefill_attribution']['preemptions']==0 for r in rows),'all_store_accept_complete_balanced':all(r['store_balance']['balanced'] is True for r in rows),'missing_store_failed_counter':'Unavailable; not assumed zero.','primary_and_secondary_intervals':a['paired_analysis'],'output_totals':a['arm_outcomes'],'resources':resources,'mechanism_by_partition':mechanism,'anchors':anchors,'quality_review':'output/prefetch-native-20261102/live-nov3-triage-confirmation-quality-review.json','production_endorsement':False,'judgment':'Do not qualify the selected cache policy for broad human-reviewed repository triage production. Pooled workflow and token-rate effects are indistinguishable from zero, while p95 TTFT and E2E regress. All four repeats in each of two partitions are slower; one favorable partition is insufficient for a postselected production claim. This conclusion is about net cache effect, not a demand that caching fix baseline reasoning.','scope_limits':['Paired t intervals condition on three fixed issue sets, not twelve independent workloads or generalization to new repositories.','Natural output lengths differ; report workflow and token rate separately.','No matched VRAM saving: serving peaks differ only 0–2MiB; startup and CUDA peaks separately recorded.','System-wide swap activity and dynamic clocks are observed, not controlled; no causal attribution to a unique arm from those counters.','All requests have natural EOS and zero preemptions, but first-admission attribution is still not measured physical GPU work/time.','Earlier historical disconnects remain failures with structural transport mitigation, not retrospectively proven causes.','Source-grounded manual quality review found material factual defects; human review required and human time saving unmeasured.','4096 identity cap fail-closed with no expiry; bounded long-running behavior and continuous endurance remain unqualified.'],'next_discovery_review':variant}
 write(H/'live-nov3-triage-confirmation-independent-assessment.json',assessment)
 inventory={'schema':'astra-triage-confirmation-handback-v1','at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'custody':'ASTRA -> ROOT','manifest_pins_checked':len(m['file_pins']),'pin_mismatches':bad,'gate_and_manifest_match':True,'supervisor_exited':True,'all_runner_descendants_exited':True,'owned_processes_remaining':[],'gpu_compute_processes':gpu,'gpu_lock_available':True,'free_bytes_before_cleanup':before,'free_bytes_after_cleanup':shutil.disk_usage(H).free,'removed_files':[],'retained_bytes':sum(p.stat().st_size for p in files),'retained_files':[{'path':str(p.relative_to(ROOT)),'bytes':p.stat().st_size} for p in files],'retention_reason':'Full compressed raw/server/console evidence, per-run pins/source archives and negative results retained for root independent verification. Large descriptive-anchor audit histories remain evidence. All logs already compressed and no disposable worktrees/downloads/checkpoints or owned processes remain. Shared caches and earlier results untouched.','analysis_receipts':[str((H/n).relative_to(ROOT)) for n in ['live-nov3-triage-confirmation-independent-analysis.json','live-nov3-triage-confirmation-independent-assessment.json','live-nov3-triage-confirmation-quality-samples.json','live-nov3-triage-confirmation-quality-review.json']]}
 write(H/'live-nov3-triage-confirmation-handback-inventory.json',inventory)
 print(json.dumps({'HTTP':http,'pins':len(m['file_pins']),'retained_bytes':inventory['retained_bytes'],'production_endorsement':False,'cleanup_complete':True},indent=2))
if __name__=='__main__':main()
